def choose_move(observation):
    def clamp_step(v):
        return 0 if v == 0 else (1 if v > 0 else -1)

    def first_point(value):
        if isinstance(value, (list, tuple)) and len(value) >= 2:
            return value[0], value[1]
        return None

    def points_from(value):
        if not value:
            return []
        pts = []
        if isinstance(value, dict):
            for k, v in value.items():
                p = first_point(v)
                if p is not None:
                    pts.append(p)
            return pts
        if isinstance(value, (list, tuple)):
            for item in value:
                p = first_point(item)
                if p is not None:
                    pts.append(p)
        return pts

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    obs = observation if isinstance(observation, dict) else {}
    env = obs.get("environment_name") or obs.get("env") or "resource_collection"

    self_pos = first_point(obs.get("self_position")) or first_point(obs.get("position")) or (0, 0)
    opp_pos = first_point(obs.get("opponent_position")) or first_point(obs.get("enemy_position")) or self_pos

    sx, sy = self_pos
    ox, oy = opp_pos

    grid_w = obs.get("grid_width") or obs.get("width") or 0
    grid_h = obs.get("grid_height") or obs.get("height") or 0

    if env == "pursuit_evasion":
        role = obs.get("self_role") or obs.get("role") or "pursuer"
        if role == "pursuer":
            return [clamp_step(ox - sx), clamp_step(oy - sy)]
        corners = []
        if grid_w and grid_h:
            corners = [(0, 0), (0, grid_h - 1), (grid_w - 1, 0), (grid_w - 1, grid_h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = max(corners, key=lambda p: manhattan(p, (ox, oy)))
        return [clamp_step(target[0] - sx), clamp_step(target[1] - sy)]

    if env == "territory_control":
        targets = points_from(obs.get("unclaimed_cells")) or points_from(obs.get("opponent_territory")) or points_from(obs.get("neutral_cells"))
        if not targets:
            return [clamp_step(ox - sx), clamp_step(oy - sy)]
        best = min(targets, key=lambda p: manhattan(p, (sx, sy)))
        return [clamp_step(best[0] - sx), clamp_step(best[1] - sy)]

    resources = points_from(obs.get("resources")) or points_from(obs.get("resource_positions")) or points_from(obs.get("items"))
    if resources:
        best = min(resources, key=lambda p: manhattan(p, (sx, sy)))
        return [clamp_step(best[0] - sx), clamp_step(best[1] - sy)]

    enemy_territory = points_from(obs.get("opponent_territory")) or points_from(obs.get("enemy_territory"))
    if enemy_territory:
        best = min(enemy_territory, key=lambda p: manhattan(p, (sx, sy)))
        return [clamp_step(best[0] - sx), clamp_step(best[1] - sy)]

    if ox != sx or oy != sy:
        return [clamp_step(ox - sx), clamp_step(oy - sy)]

    step = obs.get("step") or obs.get("turn") or 0
    if step % 4 == 0:
        return [1, 0]
    if step % 4 == 1:
        return [0, 1]
    if step % 4 == 2:
        return [-1, 0]
    return [0, -1]

